<section class="onboarding-panel onboarding-process-create">
  <div class="onboarding-panel-heading"><div><p class="onboarding-overline">NUEVO INGRESO</p><h2>Preparar un proceso</h2><p class="panel-description">Selecciona registros existentes. Se guardarán sus identificadores, no se crearán usuarios ni se copiarán datos personales.</p></div></div>
  <form class="onboarding-form" method="post" data-pending-form>
    <label class="onboarding-field"><span>Practicante</span><select name="practicante_id" required <?php echo empty($onboardingData['practicantes']) ? 'disabled' : ''; ?>><option value="">Selecciona un practicante</option><?php foreach ($onboardingData['practicantes'] as $practicante): ?><option value="<?php echo (int)$practicante['id']; ?>" <?php echo $onboardingData['selectedPracticanteId'] === (int)$practicante['id'] ? 'selected' : ''; ?>><?php echo $onboardingEscape($practicante['name']); ?> · ID <?php echo (int)$practicante['id']; ?></option><?php endforeach; ?></select><?php if (empty($onboardingData['practicantes'])): ?><small>No hay practicantes disponibles o no se encontró la tabla.</small><?php endif; ?></label>
    <label class="onboarding-field"><span>Responsable del proceso</span><select name="responsable_id" required <?php echo empty($onboardingData['usuarios']) ? 'disabled' : ''; ?>><option value="">Selecciona un usuario</option><?php foreach ($onboardingData['usuarios'] as $usuario): ?><option value="<?php echo (int)$usuario['id']; ?>"><?php echo $onboardingEscape($usuario['name']); ?> · ID <?php echo (int)$usuario['id']; ?></option><?php endforeach; ?></select></label>
    <label class="onboarding-field"><span>Fecha de inicio</span><input type="date" name="fecha_inicio"></label>
    <label class="onboarding-field"><span>Modalidad</span><select name="modalidad"><option value="presencial">Presencial</option><option value="hibrida">Híbrida</option><option value="remota">Remota</option></select></label>
    <div class="onboarding-form-actions"><span class="form-hint"><i class="fa-solid fa-link" aria-hidden="true"></i> Vinculación prevista: practicantes.id + usuarios.id</span><button class="onboarding-button" type="submit" <?php echo empty($onboardingData['canManage']) || empty($onboardingData['practicantes']) || empty($onboardingData['usuarios']) ? 'disabled' : ''; ?>><i class="fa-solid fa-plus" aria-hidden="true"></i> Crear proceso</button></div>
    <?php if (!empty($onboardingData['submissionNotice'])): ?><div class="onboarding-form-notice" role="status"><?php echo $onboardingEscape($onboardingData['submissionNotice']); ?></div><?php else: ?><div class="onboarding-form-notice" data-form-notice role="status" hidden></div><?php endif; ?>
  </form>
</section>

<section class="onboarding-panel onboarding-process-list">
  <div class="onboarding-panel-heading"><div><p class="onboarding-overline">SEGUIMIENTO</p><h2>Procesos de onboarding</h2></div><span class="onboarding-count">0 procesos</span></div>
  <div class="onboarding-table-wrap"><table class="onboarding-table"><thead><tr><th>Practicante</th><th>Responsable</th><th>Inicio</th><th>Avance</th><th>Estado</th><th></th></tr></thead><tbody><tr><td colspan="6"><div class="onboarding-empty-state compact"><span class="empty-state-icon"><i class="fa-solid fa-diagram-project" aria-hidden="true"></i></span><strong>No hay procesos registrados</strong><p>El listado se habilitará al integrar el almacenamiento del módulo.</p></div></td></tr></tbody></table></div>
</section>